const msg = $json.message || {};
const from = msg.from || {};
const chat = msg.chat || {};
const doc = msg.document || {};

// Extensiones consideradas peligrosas
const dangerousExtensions = ['exe','bat','cmd','com','scr','js','vbs','msi','jar','ps1','sh','dll','apk','pif','reg'];

const fileName = doc.file_name || '';
const parts = fileName.split('.');
const extension = parts.length > 1 ? parts[parts.length - 1].toLowerCase() : '';
const userId = from.id;

return {
  json: {
    userId: userId,
    username: from.first_name || '',
    chatId: chat.id,
    fileId: doc.file_id || '',
    fileName: fileName,
    fileSize: doc.file_size || 0,
    mimeType: doc.mime_type || '',
    extension: extension,
    hasFile: Boolean(doc.file_id),
    isDangerous: dangerousExtensions.includes(extension),
    telegramDate: new Date((msg.date || 0) * 1000).toISOString(),
  },
};

const row = $json || {};
const n = $("Normalizar y Clasificar").item.json;
const role = (row.rol || "").toString().toLowerCase();
const isAdmin = role === "admin";
const bloqueado = row.bloqueado === true;
const username = row.nombre;
return {
  json: {
    userId: n.userId,
    username: username,
    chatId: n.chatId,
    fileId: n.fileId,
    fileName: n.fileName,
    fileSize: n.fileSize,
    mimeType: n.mimeType,
    extension: n.extension,
    hasFile: n.hasFile,
    isDangerous: n.isDangerous,
    role: role || "(sin rol)",
    isAuthorized: isAdmin && !bloqueado,
    bloqueado: bloqueado,
  },
};

const nodoArchivo = $("Descargar Archivo").item;
const bin = nodoArchivo.binary || {};

const e = $("Evaluar Rol").item.json;
const n = $("Normalizar y Clasificar").item.json;

return {
  json: {
    userId: n.userId,
    username: e.username,
    chatId: n.chatId,
    fileName: n.fileName,
    extension: n.extension,
    sha256: $json.sha256,
    fileBase64: bin.data ? bin.data.data : "",
  },
  binary: bin,  // pasa el objeto binary completo al siguiente nodo
};

const row = $json || {};
const prev = row.sha256 || "";

const p = $("Preparar Archivo").item.json;
const bin = $("Preparar Archivo").item.binary || {};
const current = p.sha256;

let integrityStatus;
let riskLevel;

if (!prev) { integrityStatus = "OK"; riskLevel = "NUEVO"; }
else if (prev === current) { integrityStatus = "OK"; riskLevel = "BAJO"; }
else { integrityStatus = "INTEGRIDAD COMPROMETIDA"; riskLevel = "ALTO"; }

return {
  json: {
    userId: p.userId,
    username: p.username,
    chatId: p.chatId,
    fileName: p.fileName,
    extension: p.extension,
    sha256: current,
    prevHash: prev,
    fileBase64: p.fileBase64,
    integrityStatus,
    riskLevel,
  },
  binary: bin,  // ← rescata el binario de Preparar Archivo
};

