const analysis = $json.data.attributes;
const stats = analysis.stats;

// Cuántos motores detectaron algo malicioso
const malicious = stats.malicious || 0;
const suspicious = stats.suspicious || 0;
const total = stats.harmless + stats.malicious + stats.suspicious + stats.undetected;

// Determinar nivel de riesgo
let riskLevel;
let verdict;

if (malicious > 5) {
  riskLevel = "CRÍTICO";
  verdict = "MALWARE CONFIRMADO";
} else if (malicious > 0 || suspicious > 3) {
  riskLevel = "ALTO";
  verdict = "SOSPECHOSO";
} else {
  riskLevel = "MEDIO";
  verdict = "LIMPIO - pero hash cambió";
}

const p = $("Comparar Integridad").item.json;

return {
  json: {
    userId: p.userId,
    username: p.username,
    chatId: p.chatId,
    fileName: p.fileName,
    sha256: p.sha256,
    prevHash: p.prevHash,
    integrityStatus: p.integrityStatus,
    riskLevel: riskLevel,
    verdict: verdict,
    maliciousEngines: malicious,
    suspiciousEngines: suspicious,
    totalEngines: total,
    vtAnalysisId: $json.data.id,
  }
};

