const ci = $("Comparar Integridad").item.json;

// VirusTotal solo existe si pasó por ahí
let verdict = "N/A";
let riskLevel = ci.riskLevel;

try {
  const vt = $("Interpretar VirusTotal").item.json;
  if (vt && vt.verdict) {
    verdict = vt.verdict;
    riskLevel = vt.riskLevel;
  }
} catch(e) {}

return {
  json: {
    userId: ci.userId,
    username: ci.username,
    chatId: ci.chatId,
    fileName: ci.fileName,
    sha256: ci.sha256,
    prevHash: ci.prevHash,
    integrityStatus: ci.integrityStatus,
    riskLevel,
    verdict,
  }
};

const mimeMap = {
  'pdf': 'application/pdf',
  'jpg': 'image/jpeg',
  'jpeg': 'image/jpeg',
