  'xlsx': 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
  'zip': 'application/zip',
};

const n = $("Normalizar y Clasificar").item.json;
const expectedMime = mimeMap[n.extension] || null;
const actualMime = n.mimeType || '';
const mimeOk = !expectedMime || actualMime === expectedMime;

return {
  json: {
    ...n,
    expectedMime,
    actualMime,
    mimeOk,
    isSpoofed: !mimeOk,
  }
};

