const pesos = {
  'MALWARE CONFIRMADO': 10,
  'AMENAZA': 5,
  'INTEGRIDAD COMPROMETIDA': 4,
  'MIME_FALSIFICADO': 3,
  'RATE LIMIT EXCEDIDO': 2,
};

const rows = $input.all();
const ahora = Date.now();
const userId = $("Normalizar y Clasificar").item.json.userId;

const score = rows.reduce((total, r) => {
  const eventoTime = new Date(r.json.timestamp).getTime();
  const horasTranscurridas = (ahora - eventoTime) / (1000 * 60 * 60);

  // Descarta eventos fuera de la ventana de 24h
  if (horasTranscurridas > 24) return total;

  // Descarta eventos de otros usuarios
  if (String(r.json.user_id) !== String(userId)) return total;

  // Factor de decaimiento — eventos recientes pesan más
  const factorTiempo = 1 - (horasTranscurridas / 24);

  for (const [clave, puntos] of Object.entries(pesos)) {
    if (r.json.event?.includes(clave) || r.json.integrity_status?.includes(clave)) {
      return total + (puntos * factorTiempo);
    }
  }
  return total;
}, 0);

const n = $("Normalizar y Clasificar").item.json;

return {
  json: {
    ...n,
    riskScore: Math.round(score * 100) / 100, // redondea a 2 decimales
    debeBloquear: score >= 15,
  }
};

